427	    /**
428	     * Compute the stable identifier shared by all owners in the same household, i.e. with the same
429	     * last name (compared case-insensitively with collapsed whitespace, see
430	     * {@link #normalizeHousehold(String)}) and the same postcode. The value is deterministic in
431	     * those two fields, so two owners who share a last name and postcode are assigned the same id
432	     * automatically. It is formatted {@code 'HH-<HEX12>'} where {@code HEX12} is the first twelve
433	     * upper-cased hex characters of the SHA-256 digest of
434	     * {@code normalizedLastName + '|' + postcode}.
435	     *
436	     * @param lastName the owner's last name, possibly {@code null}
437	     * @param postcode the owner's postcode, possibly {@code null}
438	     * @return the household id, or {@code null} if either field is {@code null}
439	     */
440	    public static String householdId(String lastName, String postcode) {
441	        String normalizedLastName = normalizeHousehold(lastName);
442	        if (normalizedLastName == null || postcode == null) {
443	            return null;
444	        }
445	        String key = normalizedLastName + "|" + postcode;
446	        return "HH-" + sha256Hex(key).substring(0, 12).toUpperCase();
447	    }
448	
449	    /**
450	     * Compute the full lower-case hex SHA-256 digest of the UTF-8 bytes of {@code value}. This is the
451	     * shared primitive behind every hash-derived owner value (the household id and the customer code),
452	     * so they all agree on algorithm and encoding.
453	     *
454	     * @param value the string to digest, never {@code null}
455	     * @return the 64-character lower-case hex digest
456	     */
457	    private static String sha256Hex(String value) {
458	        try {
459	            byte[] digest = MessageDigest.getInstance("SHA-256")
460	                .digest(value.getBytes(StandardCharsets.UTF_8));
461	            StringBuilder hex = new StringBuilder(digest.length * 2);
462	            for (byte b : digest) {
463	                hex.append(String.format("%02x", b));
464	            }
465	            return hex.toString();
466	        } catch (NoSuchAlgorithmException e) {
467	            // SHA-256 is a standard algorithm required to be present on every JVM.
468	            throw new IllegalStateException("SHA-256 not available", e);
469	        }
470	    }
471	
472	    /**
473	     * Build an owner's {@code customerCode}, the stable owner identity assigned once when the owner is
474	     * created. It is formatted {@code '<REGION>-<HASH8>'} where:
475	     * <ul>
476	     *   <li>{@code REGION} is the region code derived from the postcode (see
477	     *       {@link #regionForPostcode(String)}), or {@code 'UNKNOWN'} when the postcode is absent or
478	     *       in no known range, and</li>
479	     *   <li>{@code HASH8} is the first eight upper-cased hex characters of the SHA-256 digest of the
480	     *       normalized telephone (see {@link #normalizeTelephone(String)}) concatenated with the last
481	     *       name.</li>
482	     * </ul>
483	     * The value is deterministic in the postcode, telephone and last name (e.g.
484	     * {@code 'NSW-1A2B3C4D'}); it carries no sequence number.
485	     *
486	     * @param postcode the owner's postcode, possibly {@code null}
487	     * @param telephone the owner's raw telephone, possibly {@code null}
488	     * @param lastName the owner's last name, possibly {@code null}
489	     * @return the customer code, or {@code null} if the telephone or last name is {@code null}
490	     */
491	    public static String customerCode(String postcode, String telephone, String lastName) {
492	        if (telephone == null || lastName == null) {
493	            return null;
494	        }
495	        String region = regionForPostcode(postcode);
496	        if (region == null) {
497	            region = "UNKNOWN";
498	        }
499	        String normalizedTelephone = normalizeTelephone(telephone);
500	        String key = (normalizedTelephone == null ? "" : normalizedTelephone) + lastName;
501	        return region + "-" + sha256Hex(key).substring(0, 8).toUpperCase();
502	    }
