613	    /**
614	     * Derive an owner's {@code locality}, the canonical region for the owner, from the {@code REGION}
615	     * segment of the owner's {@code customerCode} (see {@link #customerCode(String, String, String)}).
616	     * Because the customer code's region is itself derived from the postcode, the locality now shares
617	     * the owner's region-and-hash identity: it is the text before the first {@code '-'} of the customer
618	     * code. When the owner has no customer code the locality is {@code 'UNKNOWN'}.
619	     *
620	     * @param customerCode the owner's customer code, possibly {@code null}
621	     * @return the canonical region string, or {@code 'UNKNOWN'} when no customer code is present
622	     */
623	    public static String locality(String customerCode) {
624	        if (customerCode == null) {
625	            return "UNKNOWN";
626	        }
627	        int dash = customerCode.indexOf('-');
628	        return dash < 0 ? customerCode : customerCode.substring(0, dash);
629	    }
