631	    /**
632	     * Resolve the canonical region for a city from the fixed {@link #CITY_REGION} table. A city not
633	     * in the table (including {@code null}) resolves to {@code 'UNKNOWN'}.
634	     *
635	     * @param city the owner's city, possibly {@code null}
636	     * @return the matching region, or {@code 'UNKNOWN'} when the city is not in the table
637	     */
638	    private static String regionForCity(String city) {
639	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
640	    }
641	
642	    /**
643	     * Fixed region-to-postcode-range table used by {@link #isPostcodeValidForCity(String, String)}
644	     * and {@link #regionForPostcode(String)}, keyed by the canonical region. Each entry is the
645	     * inclusive low and high bound of the region's valid 4-digit postcodes
646	     * ({@code NSW} 2000-2099, {@code VIC} 3000-3099, {@code QLD} 4000-4099). A region not in this
647	     * table (including {@code 'UNKNOWN'}) places no range constraint.
648	     */
649	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
650	        "NSW", new int[] {2000, 2099},
651	        "VIC", new int[] {3000, 3099},
652	        "QLD", new int[] {4000, 4099});
653	
654	    /**
655	     * Resolve the canonical region whose postcode range contains the given postcode, using the fixed
656	     * {@link #REGION_POSTCODE_RANGES} table. A {@code null} postcode, one that is not exactly four
657	     * digits, or one that falls in no known range resolves to {@code null}.
658	     *
659	     * @param postcode the owner's postcode, possibly {@code null}
660	     * @return the matching region, or {@code null} when no range contains the postcode
661	     */
662	    private static String regionForPostcode(String postcode) {
663	        if (postcode == null || !postcode.matches("\\d{4}")) {
664	            return null;
665	        }
666	        int value = Integer.parseInt(postcode);
667	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
668	            int[] range = entry.getValue();
669	            if (value >= range[0] && value <= range[1]) {
670	                return entry.getKey();
671	            }
672	        }
673	        return null;
674	    }
675	
676	    /**
677	     * Check whether a postcode is valid for an owner's city. Postcode is optional, so a
678	     * {@code null} or empty postcode is always valid. When present it must be exactly four
679	     * digits, and when the city's region (from the fixed city-to-region table) has a known postcode
680	     * range the value must fall within that inclusive range. A city with no known region accepts
681	     * any four-digit postcode. This is the single source of
682	     * truth for postcode validity, shared by the DTO validation and any persistence path.
683	     *
684	     * @param postcode the owner's postcode, possibly {@code null}
685	     * @param city the owner's city, possibly {@code null}
686	     * @return {@code true} if the postcode is absent or valid for the city, {@code false} otherwise
687	     */
688	    public static boolean isPostcodeValidForCity(String postcode, String city) {
689	        if (postcode == null || postcode.isEmpty()) {
690	            return true;
691	        }
692	        if (!postcode.matches("\\d{4}")) {
693	            return false;
694	        }
695	        int[] range = REGION_POSTCODE_RANGES.get(regionForCity(city));
696	        if (range == null) {
697	            return true;
698	        }
699	        int value = Integer.parseInt(postcode);
700	        return value >= range[0] && value <= range[1];
701	    }
702	
703	    /**
704	     * Compute an owner's {@code checkDigit}, a single Luhn check digit (0-9) over the digits
705	     * contained in the {@code customerCode}. Non-digit characters in the code are ignored. The
706	     * value is deterministic in the customer code and is the standard Luhn check digit: each
707	     * digit is weighted right-to-left, every second digit (starting with the rightmost) is
708	     * doubled with digit sums above nine reduced by nine, and the check digit is the amount that
709	     * brings the weighted sum up to the next multiple of ten.
710	     *
711	     * @param customerCode the owner's customer code, possibly {@code null}
712	     * @return the Luhn check digit from 0 to 9, or {@code null} if the customer code is {@code null}
713	     */
714	    public static Integer checkDigit(String customerCode) {
715	        if (customerCode == null) {
716	            return null;
717	        }
718	        int sum = 0;
719	        boolean dbl = true;
720	        for (int i = customerCode.length() - 1; i >= 0; i--) {
721	            char c = customerCode.charAt(i);
722	            if (c < '0' || c > '9') {
723	                continue;
724	            }
725	            int d = c - '0';
726	            if (dbl) {
727	                d *= 2;
728	                if (d > 9) {
729	                    d -= 9;
730	                }
731	            }
732	            sum += d;
733	            dbl = !dbl;
734	        }
735	        return (10 - (sum % 10)) % 10;
736	    }
737	
738	    /**
739	     * Derive an owner's {@code contactPreference}, the preferred channel for contacting the owner.
740	     * The value is {@code 'EMAIL'} when an email is present and {@code 'PHONE'} otherwise. The value
741	     * is deterministic in the email.
742	     *
743	     * @param email the owner's email, possibly {@code null}
744	     * @return {@code 'EMAIL'} when an email is present, otherwise {@code 'PHONE'}
745	     */
746	    public static String contactPreference(String email) {
747	        return (email != null && !email.isEmpty()) ? "EMAIL" : "PHONE";
748	    }
749	
750	    /**
751	     * Derive an owner's {@code ageBand}, the band the owner's age falls into on the registration
752	     * date. The age in whole years is the number of completed years between {@code birthDate} and
753	     * {@code registrationDate}, and the band is {@code 'MINOR'} when under 18, {@code 'ADULT'} when
754	     * 18 to 64 inclusive, and {@code 'SENIOR'} when 65 or older. The value is deterministic in those
755	     * two fields and is only defined when both are present.
756	     *
757	     * @param birthDate the owner's date of birth, possibly {@code null}
758	     * @param registrationDate the owner's registration date, possibly {@code null}
759	     * @return {@code 'MINOR'}, {@code 'ADULT'} or {@code 'SENIOR'}, or {@code null} when either date
760	     *     is {@code null}
761	     */
762	    public static String ageBand(LocalDate birthDate, LocalDate registrationDate) {
763	        if (birthDate == null || registrationDate == null) {
764	            return null;
765	        }
766	        int age = Period.between(birthDate, registrationDate).getYears();
767	        if (age < 18) {
768	            return "MINOR";
769	        }
770	        if (age < 65) {
771	            return "ADULT";
772	        }
773	        return "SENIOR";
774	    }
775	
776	    protected Set<Pet> getPetsInternal() {
777	        if (this.pets == null) {
778	            this.pets = new HashSet<>();
779	        }
780	        return this.pets;
781	    }
782	
783	    protected void setPetsInternal(Set<Pet> pets) {
784	        this.pets = pets;
785	    }
786	
787	    public List<Pet> getPets() {
788	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
789	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
790	        return Collections.unmodifiableList(sortedPets);
791	    }
792	
793	    public void setPets(List<Pet> pets) {
794	        this.pets = new HashSet<>(pets);
795	    }
796	
797	    public void addPet(Pet pet) {
798	        getPetsInternal().add(pet);
799	        pet.setOwner(this);
800	    }
801	
802	    /**
803	     * Return the Pet with the given name, or null if none found for this Owner.
804	     *
805	     * @param name to test
806	     * @return true if pet name is already in use
807	     */
808	    public Pet getPet(String name) {
809	        return getPet(name, false);
810	    }
811	
812	    /**
813	     * Return the Pet with the given name, or null if none found for this Owner.
814	     *
815	     * @param name to test
816	     * @return true if pet name is already in use
817	     */
818	    public Pet getPet(String name, boolean ignoreNew) {
819	        name = name.toLowerCase();
820	        for (Pet pet : getPetsInternal()) {
821	            if (!ignoreNew || !pet.isNew()) {
822	                String compName = pet.getName();
823	                compName = compName.toLowerCase();
824	                if (compName.equals(name)) {
825	                    return pet;
826	                }
827	            }
828	        }
829	        return null;
830	    }
831	
832	    public Pet getPet(Integer petId) {
833	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
834	    }
835	
836	    @Override
837	    public String toString() {
838	        return new ToStringCreator(this)
839	
840	            .append("id", this.getId())
841	            .append("new", this.isNew())
842	            .append("lastName", this.getLastName())
843	            .append("firstName", this.getFirstName())
844	            .append("address", this.address)
845	            .append("city", this.city)
846	            .append("telephone", this.telephone)
847	            .toString();
848	    }
849	}
